const dashboardLoad={completed:0,loaded:new Set(),requiredFailures:[],optionalFailures:[]};

/** Update the visible dashboard loading progress. */
function updateLoadingNotice(){
  const notice=$("loadingNotice"),remaining=dashboardDatasets.filter(dataset=>!dashboardLoad.loaded.has(dataset.name)&&![...dashboardLoad.requiredFailures,...dashboardLoad.optionalFailures].some(failure=>failure.name===dataset.name));
  notice.hidden=false;
  notice.classList.toggle("unavailable",dashboardLoad.requiredFailures.length>0);
  notice.classList.toggle("degraded",dashboardLoad.requiredFailures.length===0&&dashboardLoad.optionalFailures.length>0);
  if(dashboardLoad.requiredFailures.length){
    notice.innerHTML=`<div><strong>Dashboard data unavailable</strong><span>${esc(dashboardLoad.requiredFailures.map(failure=>`${failure.label}: ${failure.message}`).join(" · "))}</span></div>`;
    return;
  }
  if(dashboardLoad.completed===dashboardDatasets.length){
    if(dashboardLoad.optionalFailures.length)notice.innerHTML=`<div><strong>Dashboard loaded with limited data</strong><span>${esc(dashboardLoad.optionalFailures.map(failure=>`${failure.label} unavailable`).join(" · "))}</span></div>`;
    else notice.hidden=true;
    return;
  }
  const waiting=remaining.slice(0,3).map(dataset=>dataset.label).join(", ");
  notice.innerHTML=`<span class="loading-spinner" aria-hidden="true"></span><div><strong>Loading dashboard data · ${dashboardLoad.loaded.size} of ${dashboardDatasets.length} datasets ready</strong><span>${waiting?`Waiting for ${esc(waiting)}${remaining.length>3?" and more":""}.`:"Finalizing dashboard."}</span></div>`;
}

/** Load dashboard datasets independently so completed sections render immediately. */
function loadDashboardDatasets(){
  initialize();
  updateLoadingNotice();
  dashboardDatasets.forEach(dataset=>{
    load(dataset.name)
      .then(rows=>{state[dataset.key]=rows;dashboardLoad.loaded.add(dataset.name);rebuildDerivedState();render();})
      .catch(error=>{const failure={...dataset,message:error.message};(dataset.required?dashboardLoad.requiredFailures:dashboardLoad.optionalFailures).push(failure);if(dataset.required){$("freshnessText").textContent=`Data unavailable: ${error.message}`;$("availabilityItems").innerHTML=`<span class="header-status-item unavailable" title="Required dashboard data is unavailable"><i aria-hidden="true"></i><strong>Dashboard data</strong><span class="status-info" aria-hidden="true">i</span></span>`;}})
      .finally(()=>{dashboardLoad.completed+=1;updateLoadingNotice();});
  });
}

