  document.querySelectorAll('input[name="assetDomain"]').forEach(input=>input.addEventListener("change",()=>{state.domains=new Set([...document.querySelectorAll('input[name="assetDomain"]:checked')].map(item=>item.value));clearSelectedWorkItem();render();}));
  document.querySelectorAll(".story-nav button[data-view]").forEach(button=>button.addEventListener("click",()=>{if(button.dataset.view==="data-browser"){dataBrowserState.evidenceRows=null;dataBrowserState.pendingEvidence=null;dataBrowserState.offset=0;}activateView(button.dataset.view);}));
  $("brandLogoButton").addEventListener("click",()=>{if(!$("brandLogoButton").disabled)$("customerLogoInput").click();});
  $("customerLogoInput").addEventListener("change",event=>{const file=event.target.files?.[0];event.target.value="";uploadCustomerLogo(file);});
  $("navToggle").addEventListener("click",()=>setNavigationCollapsed(!document.body.classList.contains("nav-collapsed"),true));
  $("filterToggle").addEventListener("click",()=>setFilterExpanded($("filterBar").hidden,true));
  $("statisticsPeriod").addEventListener("change",event=>{state.statisticsPeriod=event.target.value;$("customPeriodFields").hidden=state.statisticsPeriod!=="custom";renderTrend();});
  $("applyStatisticsPeriod").addEventListener("click",renderTrend);
  $("reportingEntity").addEventListener("change",event=>{state.reportingEntity=event.target.value;renderLifecycleReporting();});
  $("exportReportingCsv").addEventListener("click",exportLifecycleCsv);
  $("dataBrowserDataset").addEventListener("change",event=>{dataBrowserState.dataset=event.target.value;dataBrowserState.offset=0;dataBrowserState.query="";dataBrowserState.evidenceRows=null;$("dataBrowserSearch").value="";loadDataBrowserRows();});
  $("dataBrowserSearchButton").addEventListener("click",()=>{dataBrowserState.query=$("dataBrowserSearch").value.trim();dataBrowserState.offset=0;dataBrowserState.evidenceRows=null;loadDataBrowserRows();});
  $("dataBrowserSearch").addEventListener("keydown",event=>{if(event.key==="Enter"){$("dataBrowserSearchButton").click();}});
  $("dataBrowserPrevious").addEventListener("click",()=>{dataBrowserState.offset=Math.max(0,dataBrowserState.offset-dataBrowserState.limit);dataBrowserState.evidenceRows?renderMetricEvidencePage():loadDataBrowserRows();});
  $("dataBrowserNext").addEventListener("click",()=>{dataBrowserState.offset+=dataBrowserState.limit;dataBrowserState.evidenceRows?renderMetricEvidencePage():loadDataBrowserRows();});
  $("copyDataBrowserJson").addEventListener("click",()=>{if(!dataBrowserState.selectedRecord)return;navigator.clipboard?.writeText(JSON.stringify(dataBrowserState.selectedRecord,null,2)).then(()=>{$("copyDataBrowserJson").textContent="Copied";}).catch(()=>{$("copyDataBrowserJson").textContent="Copy unavailable";});});
  document.addEventListener("click",event=>{const controls=document.querySelector(".workspace-controls");if(!$("filterBar").hidden&&controls&&!controls.contains(event.target))setFilterExpanded(false,true);});
  document.addEventListener("keydown",event=>{if(event.key==="Escape"&&!$("filterBar").hidden){setFilterExpanded(false,true);$("filterToggle").focus();}});
  $("resetFilters").addEventListener("click",resetFilters);
  $("clearPivot").addEventListener("click",()=>{clearSelectedWorkItem();renderPivot();});
