/** Rebuild indexes and generated filter options after a dataset arrives. */
function rebuildDerivedState(){
  const selectedTeam=state.team,selectedSubscription=state.subscription;
  const snapshotTimes=[...state.runs,...state.findings,...state.devices].map(row=>Date.parse(row.SnapshotTimeUtc)).filter(Number.isFinite);
  state.snapshotTimeMs=snapshotTimes.length?Math.max(...snapshotTimes):NaN;
  state.recommendationsById.clear();
  state.subscriptionInventoryById.clear();
  state.recommendationMachinesByRecommendation.clear();
  state.findingsByRecommendation.clear();
  state.watchlistCves.clear();
  state.recommendations.forEach(row=>state.recommendationsById.set(String(row.RecommendationId||""),row));
  state.subscriptions.forEach(row=>{if(row.SubscriptionId)state.subscriptionInventoryById.set(String(row.SubscriptionId),row);});
  state.recommendationMachines.forEach(row=>{const id=String(row.RecommendationId||"");if(!id)return;const rows=state.recommendationMachinesByRecommendation.get(id)||[];rows.push(row);state.recommendationMachinesByRecommendation.set(id,rows);});
  const vulnerabilityRecommendationByProduct=new Map(state.recommendations.filter(row=>recommendationKind(row)==="Vulnerability").map(row=>[String(row.ProductName||"").toLowerCase(),row]));
  state.findings.forEach(row=>{let id=String(row.RecommendationId||""),assigned=state.recommendationsById.get(id);if(normalizedCve(row.CveId)&&(!assigned||recommendationKind(assigned)!=="Vulnerability")){const fallback=vulnerabilityRecommendationByProduct.get(String(row.SoftwareName||"").toLowerCase());if(fallback)id=String(fallback.RecommendationId);}if(!id)return;const rows=state.findingsByRecommendation.get(id)||[];rows.push(row);state.findingsByRecommendation.set(id,rows);});
  state.findings.forEach(row=>{const cve=normalizedCve(row.CveId);if(!cve)return;const evidence=state.watchlistCves.get(cve)||new Set();exploitEvidence(row).forEach(value=>evidence.add(value));if(evidence.size)state.watchlistCves.set(cve,evidence);});
  $("teamFilter").querySelectorAll("option:not(:first-child)").forEach(option=>option.remove());
  [...new Set(state.findings.map(row=>row.OwnerTeam).filter(Boolean))].sort().forEach(team=>$("teamFilter").insertAdjacentHTML("beforeend",`<option>${esc(team)}</option>`));
  const evidenceRows=[...state.findings,...state.recommendationMachines],inventoryIds=[...state.subscriptionInventoryById.keys()],supplementalRows=inventoryIds.length?evidenceRows.filter(row=>row.DataOrigin==="Synthetic"):evidenceRows;
  $("subscriptionFilter").querySelectorAll("option:nth-child(n+3)").forEach(option=>option.remove());
  [...new Set([...inventoryIds,...supplementalRows.map(row=>row.SubscriptionId).filter(Boolean)])].sort((left,right)=>subscriptionLabel(left).localeCompare(subscriptionLabel(right))).forEach(subscription=>$("subscriptionFilter").insertAdjacentHTML("beforeend",`<option value="${esc(subscription)}">${esc(subscriptionLabel(subscription))}</option>`));
  $("teamFilter").value=[...$("teamFilter").options].some(option=>option.value===selectedTeam)?selectedTeam:"All";
  $("subscriptionFilter").value=[...$("subscriptionFilter").options].some(option=>option.value===selectedSubscription)?selectedSubscription:"All";
}

loadDashboardDatasets();

/** Activate view for the dashboard. */
function activateView(view){
  if(view==="data-browser"&&!state.dataBrowserEnabled)return;
  document.querySelectorAll(".story-nav button,.story").forEach(node=>node.classList.remove("active"));
  const button=document.querySelector(`.story-nav button[data-view="${view}"]`),section=$(view);if(!button||!section)return;
  button.classList.add("active");section.classList.add("active");state.activeView=view;render();
  if(view==="data-browser")loadDataBrowserCatalog();
  requestAnimationFrame(()=>window.scrollTo(0,0));
}

/** Defender recommendation url for the dashboard. */
function defenderRecommendationUrl(){return DEFENDER_RECOMMENDATIONS_URL;}
/** Clear selected work item for the dashboard. */
function clearSelectedWorkItem(){state.selectedRecommendationId="";state.detailRecommendationIds=[];state.selectedEntity=null;state.selectedCveDialogId="";document.body.classList.remove("pivot-detail-open");$("pivotPanel")?.classList.remove("fullscreen-mode");if($("pivotBackdrop"))$("pivotBackdrop").hidden=true;}
/** Update recommendation handoff status for the dashboard. */
function updateRecommendationHandoffStatus(){const recommendation=state.recommendationsById.get(state.selectedRecommendationId);if(recommendation?.DataOrigin==="Live")$("pivotActionStatus").textContent="Opens Exposure Recommendations. Select Vulnerabilities and paste the copied reference.";}
/** Defender device url for the dashboard. */
function defenderDeviceUrl(device){const id=String(device.DeviceId||"");return id?`https://security.microsoft.com/machines/${encodeURIComponent(id)}`:"https://security.microsoft.com/machines";}
/** Copy recommendation reference for the dashboard. */
function copyRecommendationReference(recommendation,message){const text=`${recommendation.RecommendationName}\nRecommendation ID: ${recommendation.RecommendationId}`;navigator.clipboard?.writeText(text).then(()=>{$("pivotActionStatus").textContent=message;}).catch(()=>{$("pivotActionStatus").textContent=`Recommendation ID: ${recommendation.RecommendationId}`;});}

/** Finding domain for the dashboard. */
function findingDomain(row){if(!assetClassMatches(row)||!subscriptionMatches(row))return"OutOfScope";return row.AssetClass==="AzureCloud"?"Cloud":"Devices";}
/** Recommendation kind for the dashboard. */
function recommendationKind(row){const text=`${row.RecommendationName||""} ${row.SubCategory||""}`.toLowerCase();return ["securityupdate","update"].includes(String(row.RemediationType).toLowerCase())||/\bvulnerabilit(?:y|ies)\b/.test(text)?"Vulnerability":"Misconfiguration";}
/** Finding kind for the dashboard. */
function findingKind(row){const recommendation=state.recommendationsById.get(String(row.RecommendationId||""));return recommendation?recommendationKind(recommendation):"Vulnerability";}
/** Normalized cve for the dashboard. */
function normalizedCve(value){return String(value||"").trim().toUpperCase();}
/** Exploit evidence for the dashboard. */
function exploitEvidence(row){return [["Verified",row.VerifiedExploitAvailable],["Public",row.PublicExploitAvailable],["Exploit kit",row.ExploitKitAvailable]].filter(([,value])=>truthy(value)).map(([label])=>label);}
/** Watchlist evidence for the dashboard. */
