/** Render for the dashboard. */
function render(){
  const rows=filteredFindings(), current=rows.filter(open);
  const recommendations=filteredRecommendations();
  const latest=state.runs.slice().sort((a,b)=>String(b.SnapshotTimeUtc).localeCompare(String(a.SnapshotTimeUtc)))[0];
  const health=collectionHealth();
  $("freshnessText").textContent=latest?formatUtc(latest.SnapshotTimeUtc):"No matching snapshot";
  $("healthDot").style.background=health.status==="available"?"var(--green)":health.status==="unavailable"?"var(--red)":"var(--amber)";
  renderAvailability();
  $("filterCount").textContent=`${fmt(current.length)} open findings · ${fmt(recommendations.length)} recommendations · ${fmt(filteredRemediations().length)} remediation activities`;
  renderScope(current,recommendations);
  if(state.activeView==="executive"){
    renderExecutive(recommendations,rows);
    cards("severityCards",severityCardItems(rows),"");
    renderSlaBreakdown("executiveSlaBreakdown",rows);
    cards("overviewSlaCards",slaCardItems(rows),"");
  }else if(state.activeView==="overview"){
    const known=current.filter(row=>isWatchlistCve(row.CveId));
    const watchlist=[...known.reduce((byCve,row)=>{const cve=normalizedCve(row.CveId),existing=byCve.get(cve);if(!existing||Number(row.PriorityScore)>Number(existing.PriorityScore))byCve.set(cve,row);return byCve;},new Map()).values()].map(row=>({...row,WatchlistEvidence:watchlistEvidence(row.CveId),AffectedDevices:new Set(known.filter(item=>normalizedCve(item.CveId)===normalizedCve(row.CveId)).map(item=>item.DeviceId)).size}));
    const findingDisplay=current.map(row=>({...row,WatchlistEvidence:watchlistEvidence(row.CveId)||"Not listed"}));
    table("findingsTable",["Severity","CveId","WatchlistEvidence","SoftwareName","OSPlatform","DeviceName","AssetClass","PriorityScore"],findingDisplay.filter(row=>["Critical","High"].includes(row.Severity)).sort((a,b)=>b.PriorityScore-a.PriorityScore).slice(0,80),true);
    table("exploitTable",["Severity","CveId","WatchlistEvidence","AffectedDevices","SoftwareName"],watchlist.sort((a,b)=>b.PriorityScore-a.PriorityScore).slice(0,60),true);
  }else if(state.activeView==="workstations"){
    renderWorkstations(rows);
  }else if(state.activeView==="recommendations"){
    renderRecommendations(recommendations);
  }else if(state.activeView==="priority"){
    renderPriority(recommendations);
  }else if(state.activeView==="sla"){
    cards("slaCards",slaCardItems(rows),"");
    renderSlaGraphs(rows);
    renderRemediationOutcomes(rows);
    renderRemediationActivities(filteredRemediations());
  }else if(state.activeView==="trend"){
    renderTrend();
  }
  renderPivot();
  updateRecommendationHandoffStatus();
}

